def make_africa_dict(item):
    slug, name, code, cap, pop, area, lang, curr, gov, lead, gdp, gdp_pc, inf, unemp, sh_pct, ti_r, ti_s, pr_s, de_facto = item
    return {
        "slug": slug,
        "name": name,
        "official_name": f"{name} Cumhuriyeti" if "Cumhuriyet" in gov else f"{name}",
        "code": code,
        "region": "africa",
        "capital": cap,
        "pop": pop,
        "area_km2": area,
        "languages": lang,
        "currency": curr,
        "gov_type": gov,
        "official_leader": lead,
        "de_facto_power": de_facto,
        "geostrategy": f"{cap} merkezli Afrika kıtası kritik maden ve stratejik geçiş koridoru.",
        "alliances": "Afrika Birliği / ECOWAS / SADC",
        "gdp": gdp,
        "gdp_pc": gdp_pc,
        "inflation": inf,
        "unemployment": unemp,
        "debt_to_gdp": 60.0,
        "exports": ["Maden ve Emtia", "Petrol / Gaz", "Tarım Ürünleri"],
        "imports": ["İşlenmiş Yakıt", "Gıda ve Tahıl", "Makineler"],
        "partners": ["Çin", "Fransa", "Hindistan", "BAE", "Bölgesel Komşular"],
        "shadow_economy_pct": sh_pct,
        "ti_rank": ti_r,
        "ti_score": ti_s,
        "press_score": pr_s,
        "fragility_score": 85.0,
        "oligarchy_level": "Kritik" if sh_pct > 35 else "Yüksek",
        "history_faults": f"{name} modern tarihinde sömürge sınırları travması, askeri darbeler ve etnik/kabile çatışmaları belirleyicidir.",
        "cultural_faults": "Kabile meclisleri ile modern devlet aygıtı arasındaki uyumsuzluk ve genç işsizliği.",
        "judicial_status": "Yargı yürütmenin ve cumhurbaşkanlığı klanının doğrudan vesayeti altındadır.",
        "security_apparatus": "Başkanlık Muhafızları, Ulusal Ordu ve İstihbarat Teşkilatı.",
        "foreign_influence": "Eski sömürgeci güçler (Fransa/İngiltere), Rus paramiliter varlığı ve Çin altyapı kredileri rekabeti.",
        "offshore_routes": "Dubai, İsviçre ve Mauritius.",
        "media_landscape": f"{name} basını sansür, yayın durdurma ve gazetecilere yönelik yargısal tacizle baskılanmaktadır.",
        "oligarchs": [
            (f"{name} Ulusal Maden ve Kaynak Konsorsiyumu", "Doğal Kaynaklar ve İhracat Tekeli", "Madencilik / Enerji", "Devlet Başkanı Ailesi ve Askeri Elitler", 350, "Ulusal Maden Bakanlığı Kayıtları"),
            (f"{name} İthalat ve Dağıtım Şirketler Ağı", "Gıda, Akaryakıt ve Kamu İhaleleri", "Ticaret / Lojistik", "Siyasi Bürokrasiyle Entegre Tüccarlar", 220, "Gümrük İdaresi Bültenleri")
        ]
    }

for item in GENERIC_AFRICA_DATA:
    AFRICA_COUNTRIES.append(make_africa_dict(item))
